export const noteIdValidation = z.object({
  id: z
    .string()
    .min(1, "ID is required")
    .refine((val) => mongoose.Types.ObjectId.isValid(val), {
      message: "Invalid MongoDB ObjectId",
    }),
});

export const createNoteValidation = z.object({
  title: z
    .string({
      error: (iss) =>
