import Note from "../models/note.model";
import AppError from "../utils/AppError";

import type { Request, Response, NextFunction } from "express";
import {
  createNoteValidation,
  noteIdValidation,
  updateNoteValidation,
} from "../validators/validations";

// getNotes controller
export const getNotes = async (
  req: Request,
  res: Response,
  next: NextFunction,
) => {
  try {
    // get the user id from req.user
    const user = req.user!._id;

    // get the params
    const page = Number(req.query.page) || 1;
    const limit = Number(req.query.limit) || 10;
    const skip = (page - 1) * limit;

    // get how many notes user have in the database
    const totalNotes = await Note.countDocuments({ user });

    // get all the notes from the database
    const notes = await Note.find({ user })
      .populate("user", "-password")
      .sort({ updatedAt: -1 })
      .skip(skip)
      .limit(limit);

    // check if more notes exist
    const hasMore = skip + notes.length < totalNotes;

    return res.status(200).json({
      success: true,
      notes,
      hasMore,
      currentPage: page,
    });
  } catch (error: any) {
    next(error);
  }
};

// searchedNotes controller
export const searchedNotes = async (
  req: Request,
  res: Response,
  next: NextFunction,
) => {
  try {
    // get the user id from req.user
    const user = req.user!._id;

    const query = req.query.q as string;
    const page = Number(req.query.page) || 1;
    const limit = Number(req.query.limit) || 10;
    const skip = (page - 1) * limit;

    // validation
    if (!query) {
      return res.status(400).json({ message: "Query is required" });
    }

    if (typeof query === "string" && query.trim() === "") {
      return next(new AppError(400, "Search query cannot be empty."));
    }

    // get the searchedNotes from the database
    const notes = await Note.find({
      $and: [
        { user },
        {
          $or: [
            { title: { $regex: query, $options: "i" } },
            { content: { $regex: query, $options: "i" } },
          ],
        },
      ],
    })
      .populate("user", "-password")
      .sort({ updatedAt: -1 })
      .skip(skip)
      .limit(limit);

    // get how many searched notes exist in the database
    const totalSearchedNotes = await Note.countDocuments({
      $and: [
        { user },
        {
          $or: [
            { title: { $regex: query, $options: "i" } },
            { content: { $regex: query, $options: "i" } },
          ],
        },
      ],
    });

    // check if more searched notes exist
    const hasMore = skip + notes.length < totalSearchedNotes;

    // return success response
    return res.status(200).json({
      success: true,
      notes,
      hasMore,
      currentPage: page,
    });
  } catch (error: any) {
    next(error);
  }
};

// getNote controller
export const getNote = async (
  req: Request,
  res: Response,
  next: NextFunction,
) => {
  try {
    // validation
    const result = noteIdValidation.safeParse(req.params);

    if (!result.success) {
      return next(
        new AppError(
          400,
          result.error.issues[0]?.message || "Validation error.",
        ),
      );
    }

    // get the id
    const id = result.data.id;

    // find the note from the database
    const note = await Note.findOne({ _id: id, user: req.user!._id }).populate(
      "user",
      "-password",
    );

    // returns if no note found
    if (!note) {
      return next(new AppError(404, "Note not found."));
    }

    // return success response
    return res.status(200).json({
      success: true,
      note,
    });
  } catch (error: any) {
    next(error);
  }
};

// createNote controller
export const createNote = async (
  req: Request,
  res: Response,
  next: NextFunction,
) => {
  try {
    // validation
