};

// updateNote controller
export const updateNote = async (
  req: Request,
  res: Response,
  next: NextFunction,
) => {
  try {
    // validation
    const paramsResult = noteIdValidation.safeParse(req.params);
    if (!paramsResult.success) {
      return next(
        new AppError(
          400,
          paramsResult.error.issues[0]?.message || "Validation error.",
        ),
      );
    }

    const bodyResult = updateNoteValidation.safeParse(req.body);
    if (!bodyResult.success) {
      return next(
        new AppError(
          400,
          bodyResult.error.issues[0]?.message || "Validation error.",
        ),
      );
    }

    const { id } = paramsResult.data;
    const data = bodyResult.data;

    // update the note
    const updatedNote = await Note.findOneAndUpdate(
      { _id: id, user: req.user!._id },
      { $set: data },
      { new: true },
    );

    // return if not updated
    if (!updatedNote) {
      return next(new AppError(404, "Note not found."));
    }

    // success response
    return res.status(200).json({
      success: true,
      note: updatedNote,
    });
  } catch (error: any) {
    next(error);
  }
};

// deleteNote controller
export const deleteNote = async (
  req: Request,
  res: Response,
  next: NextFunction,
) => {
  try {
    // validation
    const result = noteIdValidation.safeParse(req.params);

    if (!result.success) {
      return next(
        new AppError(
          400,
          result.error.issues[0]?.message || "Validation error.",
        ),
      );
    }

    const { id } = result.data;

    // delete the note
    const deletedNote = await Note.findOneAndDelete({
      _id: id,
      user: req.user!._id,
    });

    if (!deletedNote) {
      return next(new AppError(404, "Note not found."));
    }

    // success response
    return res.status(200).json({
      success: true,
      message: "Note has been deleted.",
    });
  } catch (error: any) {
    next(error);
  }
};

